import { program } from 'commander';
import { enterProjectRoot } from './core/project-root.js';
import { requireCurrentLayout } from './core/workdir.js';
import { readCliVersion } from './core/capabilities.js';
import { registerLogin } from './commands/login.js';
import { registerInit } from './commands/init.js';
import { registerAdd } from './commands/add.js';
import { registerDeploy } from './commands/deploy.js';
import { registerStatus } from './commands/status.js';
import { registerDiff } from './commands/diff.js';
import { registerRun } from './commands/run.js';
import { registerPull } from './commands/pull.js';
import { registerMigrate } from './commands/migrate.js';
import { registerFetch } from './commands/fetch.js';
import { registerReset } from './commands/reset.js';
import { registerWebhook } from './commands/webhook.js';
import { registerCompletion } from './commands/completion.js';
import { registerUpgrade } from './commands/upgrade.js';

const LAYOUT_EXEMPT = new Set(['upgrade', 'login', 'completion', '__complete']);

program
  .name('tgcloud')
  .description('CLI for the Telegram serverless platform')
  .version(readCliVersion())
  .option('--debug', 'Log HTTP requests and responses')
  .option('--no-pager', 'Disable the pager; write output straight to stdout')
  .hook('preAction', (thisCommand, actionCommand) => {
    const opts = thisCommand.opts();
    if (opts.debug) process.env.TGCLOUD_DEBUG = '1';
    // --no-pager sets opts.pager to false.
    if (opts.pager === false) process.env.TGCLOUD_NO_PAGER = '1';

    // Run from the project root (nearest ancestor with .tgcloud/). `init`
    // creates a project in the current directory instead.
    const name = actionCommand.name();
    if (name === 'init') return;
    const root = enterProjectRoot();
    // A pre-0.2.0 layout must go through `upgrade` first.
    if (root && !LAYOUT_EXEMPT.has(name)) requireCurrentLayout();
  });

registerLogin(program);
registerInit(program);
registerAdd(program);
registerDeploy(program);
registerStatus(program);
registerDiff(program);
registerRun(program);
registerPull(program);
registerFetch(program);
registerReset(program);
registerMigrate(program);
registerWebhook(program);
registerCompletion(program);
registerUpgrade(program);

program.parse();
